import { Fragment } from "react"
import { Port, type Via } from "tscircuit"

// The native Via constructor runs before it has a four-layer board parent.
// Add the missing inner-layer ports to this same through via before rendering.
const attachInnerLayerPorts = (via: Via | null) => {
  if (!via) return
  for (const layer of ["inner1", "inner2"] as const) {
    if (via.children.some(child => child.name === layer)) continue
    const port = new Port({ name: layer, layer })
    port.registerMatch(via)
    via.add(port)
  }
}

