export const BoardRouting = () => <>
  {vias.map(v => <Fragment key={v.name}><via {...{ ref: attachInnerLayerPorts }} name={v.name} pcbX={v.x} pcbY={v.y}
    connectsTo={`net.${v.net}`} layers={["top", "inner1", "inner2", "bottom"]}
    fromLayer="top" toLayer="bottom" holeDiameter="0.20mm" outerDiameter="0.45mm" /></Fragment>)}
  {routes.map((r, i) => <Fragment key={i}><trace name={`ROUTE_${r.net}_${i}`}
    from={r.from} to={`net.${r.net}`} thickness={r.width} maxViaCount={0}
    maxLength={r.net.startsWith("X48_") ? "6mm" : r.net.startsWith("X32_") ? "5mm" : undefined}
    pcbPath={[...r.points.map(([x,y]) => ({x,y})), ...(r.to.startsWith("net.") ? [] : [r.to])]} /></Fragment>)}
</>
